import { useState, useEffect, useCallback, useRef } from "react";
import "./App.css";
import {
  loadLogData,
  loadLogDataFromFile,
  ProcessedKernel,
  processKernelData,
  getIRType,
  processArrayBuffer,
} from "./utils/dataLoader";
import { useIframeMessaging } from "./hooks/useIframeMessaging";
import CodeView from "./pages/CodeView";
import FileDiffView from "./pages/FileDiffView";
import SingleCodeViewer from "./components/SingleCodeViewer";
import ComparisonFixture from "./components/ComparisonFixture";
import SingleFixture from "./components/SingleFixture";
import KernelOverview from "./pages/KernelOverview";
import IRAnalysis from "./pages/IRAnalysis";
import DataSourceSelector from "./components/DataSourceSelector";
import WelcomeScreen from "./components/WelcomeScreen";
import ExternalLink from "./components/ExternalLink";
import { useFileDiffSession } from "./context/FileDiffSession";
import { GitHubIcon, BookOpenIcon } from "./components/icons";
import ShareButton from "./components/ShareButton";

/**
 * Helper function to find a kernel by its hash
 */
const findKernelByHash = (hash: string, kernels: ProcessedKernel[]): number => {
  return kernels.findIndex(kernel =>
    kernel.metadata?.hash === hash
  );
};

/**
 * Main application component that handles data loading,
 * state management, and rendering different views.
 */
function App() {
  const sess = useFileDiffSession();
  const initialParams = new URLSearchParams(window.location.search);
  const initialJsonUrl = initialParams.get("json_url");
  const initialView = initialParams.get("view");
  // Store processed kernel data from log file
  const [kernels, setKernels] = useState<ProcessedKernel[]>([]);
  // Track loading state for displaying loading indicator
  const [loading, setLoading] = useState<boolean>(() => !!initialJsonUrl);
  // Store error message if data loading fails
  const [error, setError] = useState<string | null>(null);
  // Track active tab (overview or code comparison)
  const [activeTab, setActiveTab] = useState<string>(() => initialView === "file_diff" ? "file_diff" : "overview");
  // Keep-alive: main tabs that have been mounted at least once stay mounted
  // and are hidden with display:none instead of unmounting. Mounting and
  // unmounting the Monaco diff editor and the full-DOM code viewers costs
  // seconds per switch (measured); hiding is free. Only the initial tab is
  // mounted eagerly; the rest mount on first visit.
  const [visitedTabs, setVisitedTabs] = useState<Set<string>>(
    () => new Set([initialView === "file_diff" ? "file_diff" : "overview"])
  );
  // Track which IR file is selected for viewing
  const [selectedIR, setSelectedIR] = useState<string | null>(null);
  // Track which kernel is currently selected
  const [selectedKernel, setSelectedKernel] = useState<number>(-1);
  // Track if data has been loaded
  const [dataLoaded, setDataLoaded] = useState<boolean>(false);
  // Track if welcome screen should be shown (even when data is loaded)
  const [showWelcome, setShowWelcome] = useState<boolean>(() => !initialJsonUrl && initialView !== "file_diff");
  // Track the loaded data source URL
  const [loadedUrl, setLoadedUrl] = useState<string | null>(null);
  // Stable identity of the currently loaded data source (§4.2.1/R4): set
  // once per completed load, reused across ordinary rerenders. Shape
  // `<kind>:<locator>#<loadSeq>` — never derived from the page URL slot, so
  // two local files, URL->local switches, and repeated URL loads each get a
  // distinct identity. Only load-completion handlers bump the
  // sequence; render never mints IDs. The pre-load sentinel "no-source" is
  // exempt from the shape: nothing parses this string (buildKernelKey only
  // JSON-wraps it).
  const [sourceIdentity, setSourceIdentity] = useState<string>("no-source");
  const loadSeqRef = useRef(0);
  const nextSourceIdentity = useCallback((kind: string, locator: string) => {
    loadSeqRef.current += 1;
    return `${kind}:${locator}#${loadSeqRef.current}`;
  }, []);
  // Track if URL input is shown
  const [showUrlInput, setShowUrlInput] = useState<boolean>(false);

  /**
   * Handler for ArrayBuffer data received from parent iframe
   * Processes the data and updates the kernel state
   */
  const handleIframeData = useCallback(async (data: ArrayBuffer) => {
    try {
      setLoading(true);
      setError(null);

      // Process the ArrayBuffer data
      const logEntries = await processArrayBuffer(data);
      const processedKernels = processKernelData(logEntries);

      if (processedKernels.length > 0) {
        setKernels(processedKernels);
        setSelectedKernel(0);
        setDataLoaded(true);
        setShowWelcome(false); // Hide welcome screen when data is loaded
        setLoadedUrl(null); // Data came from iframe, not URL
        setSourceIdentity(nextSourceIdentity("iframe", "parent-window"));
      } else {
        setError("No kernels found in the received data.");
      }
    } catch (err) {
      console.error("Error processing iframe data:", err);
      setError(`Failed to process data: ${err instanceof Error ? err.message : String(err)}`);
      throw err; // Re-throw so iframe messaging can send ERROR response
    } finally {
      setLoading(false);
    }
  }, [nextSourceIdentity]);

  // Set up iframe messaging for communication with parent window
  useIframeMessaging({
    onDataReceived: handleIframeData,
    debug: false,
  });

  /**
   * Core URL loading logic — all setState happens after await (safe for effects)
   */
  const loadUrlData = useCallback(async (url: string, view?: string | null, kernelHash?: string | null) => {
    const logEntries = await loadLogData(url);
    const processedKernels = processKernelData(logEntries);

    if (processedKernels.length > 0) {
      setKernels(processedKernels);

      let kernelIndex = 0;
      if (kernelHash) {
        const foundIndex = findKernelByHash(kernelHash, processedKernels);
        if (foundIndex >= 0) {
          kernelIndex = foundIndex;
        } else {
          console.log(`Kernel hash ${kernelHash} not found, selected first kernel`);
        }
      }

      setSelectedKernel(kernelIndex);

      if (view === "ir_code_comparison") {
        setActiveTab("comparison");
      } else if (view === "file_diff") {
        setActiveTab("file_diff");
      } else if (view === "ir_analysis") {
        setActiveTab("ir_analysis");
      }
      setDataLoaded(true);
      setShowWelcome(false);
      setLoadedUrl(url);
      setSourceIdentity(nextSourceIdentity("url", url));

      const newUrl = new URL(window.location.href);
      newUrl.searchParams.set("json_url", url);
      if (view === "ir_code_comparison") {
        newUrl.searchParams.set("view", "ir_code_comparison");
      } else if (view === "file_diff") {
        newUrl.searchParams.set("view", "file_diff");
      } else if (view === "ir_analysis") {
        newUrl.searchParams.set("view", "ir_analysis");
      }
      if (kernelHash) {
        const foundIndex = findKernelByHash(kernelHash, processedKernels);
        if (foundIndex >= 0) {
          newUrl.searchParams.set("kernel_hash", kernelHash);
        }
      }
      window.history.replaceState({}, "", newUrl.toString());
    } else {
      console.warn("No kernels found in the URL data");
      setError("No kernels found in the URL data. Please check the file format.");
    }
  }, [nextSourceIdentity]);

  /**
   * Handles loading data from a custom URL (user-triggered, wraps with loading/error state)
   */
  const handleUrlSelected = useCallback(async (url: string, initialView?: string | null, kernelHash?: string | null) => {
    try {
      setLoading(true);
      setError(null);
      await loadUrlData(url, initialView, kernelHash);
    } catch (err) {
      console.error("Error loading data from URL:", err);
      setError(`Failed to load from URL: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setLoading(false);
    }
  }, [loadUrlData]);

  // Load data from URL on mount (loading state initialized via lazy init)
  useEffect(() => {
    if (!initialJsonUrl) return;
    const view = initialParams.get("view");
    const kernelHash = initialParams.get("kernel_hash");

    loadLogData(initialJsonUrl)
      .then(logEntries => {
        const processedKernels = processKernelData(logEntries);
        if (processedKernels.length > 0) {
          setKernels(processedKernels);

          let kernelIndex = 0;
          if (kernelHash) {
            const foundIndex = findKernelByHash(kernelHash, processedKernels);
            if (foundIndex >= 0) {
              kernelIndex = foundIndex;
            } else {
              console.log(`Kernel hash ${kernelHash} not found, selected first kernel`);
            }
          }
          setSelectedKernel(kernelIndex);

          if (view === "ir_code_comparison") {
            setActiveTab("comparison");
          } else if (view === "file_diff") {
            setActiveTab("file_diff");
          } else if (view === "ir_analysis") {
            setActiveTab("ir_analysis");
          }
          setDataLoaded(true);
          setShowWelcome(false);
          setLoadedUrl(initialJsonUrl);
          setSourceIdentity(nextSourceIdentity("url", initialJsonUrl));

          const newUrl = new URL(window.location.href);
          newUrl.searchParams.set("json_url", initialJsonUrl);
          if (view === "ir_code_comparison") newUrl.searchParams.set("view", "ir_code_comparison");
          else if (view === "file_diff") newUrl.searchParams.set("view", "file_diff");
          else if (view === "ir_analysis") newUrl.searchParams.set("view", "ir_analysis");
          if (kernelHash) {
            const fi = findKernelByHash(kernelHash, processedKernels);
            if (fi >= 0) newUrl.searchParams.set("kernel_hash", kernelHash);
          }
          window.history.replaceState({}, "", newUrl.toString());
        } else {
          console.warn("No kernels found in the URL data");
          setError("No kernels found in the URL data. Please check the file format.");
        }
      })
      .catch(err => {
        console.error("Error loading data from URL:", err);
        setError(`Failed to load from URL: ${err instanceof Error ? err.message : String(err)}`);
      })
      .finally(() => {
        setLoading(false);
      });

    const newUrl = new URL(window.location.href);
    newUrl.searchParams.set("json_url", initialJsonUrl);
    window.history.replaceState({}, "", newUrl.toString());
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /**
   * Generic data loading function that handles both URLs and local files
   * @param source - Either a URL string or a File object
   */
  const loadData = async (source: string | File) => {
    try {
      setLoading(true);
      setError(null);

      // Get URL parameters for view and kernel hash
      const params = new URLSearchParams(window.location.search);
      const view = params.get("view");
      const kernelHash = params.get("kernel_hash");

      // Load log entries based on source type
      const logEntries = typeof source === 'string'
        ? await loadLogData(source)
        : await loadLogDataFromFile(source);

      // Process raw log entries into kernel data structures
      const processedKernels = processKernelData(logEntries);

      if (processedKernels.length > 0) {
        setKernels(processedKernels);

        // First, determine which kernel to select
        let kernelIndex = 0; // Default to first kernel
        if (kernelHash) {
          const foundIndex = findKernelByHash(kernelHash, processedKernels);
          if (foundIndex >= 0) {
            kernelIndex = foundIndex;
          }
        }

        // Set the selected kernel
        setSelectedKernel(kernelIndex);

        // Then, determine which view to show
        if (view === "ir_code_comparison") {
          setActiveTab("comparison");
        } else if (view === "file_diff") {
          setActiveTab("file_diff");
        } else if (view === "ir_analysis") {
          setActiveTab("ir_analysis");
        }

        setDataLoaded(true);
        setShowWelcome(false);
        // Covers bundled-example URL strings and local File objects; the
        // page URL slot is intentionally not read here.
        setSourceIdentity(
          typeof source === "string"
            ? nextSourceIdentity("url", source)
            : nextSourceIdentity("local", source.name)
        );
      } else {
        console.warn("No kernels found in the processed data");
        const errorMsg = typeof source === 'string'
          ? "No kernels found in the default data file. Please try loading a different file."
          : "No kernels found in the selected file. Please check the file format.";
        setError(errorMsg);
      }
    } catch (err) {
      console.error(`Error loading data from ${typeof source === 'string' ? 'URL' : 'file'}:`, err);
      const errorMsg = typeof source === 'string'
        ? `Failed to load default data: ${err instanceof Error ? err.message : String(err)}`
        : `Failed to load from local file: ${err instanceof Error ? err.message : String(err)}`;
      setError(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  /**
   * Loads one of the bundled example traces from the public directory.
   *
   * Filenames are fixed by `tritonparse.tools.generate_examples`, which keeps
   * the trace-log naming convention the parser requires; see BUNDLED_EXAMPLES.
   */
  const loadBundledExample = async (fileName: string) => {
    await loadData(`./${fileName}`);
  };

  /**
   * Handles loading data from a local file
   */
  const handleFileSelected = async (file: File) => {
    await loadData(file);
  };

  /**
   * Opens the URL input field
   */
  const openUrlInput = () => {
    setShowUrlInput(true);
    // Focus on the input field after it becomes visible
    setTimeout(() => {
      const urlInput = document.querySelector('input[type="url"]');
      if (urlInput && urlInput instanceof HTMLInputElement) {
        urlInput.focus();
      }
    }, 100);
  };

  /**
   * Handles selection of an IR file for detailed viewing
   */
  const handleViewSingleIR = (irType: string) => {
    setSelectedIR(irType);
  };

  /**
   * Handles returning from single IR view to overview/comparison
   */
  const handleBackFromIRView = () => {
    setSelectedIR(null);
  };

  /**
   * Handles selection of a kernel from the list
   */
  const handleSelectKernel = (index: number) => {
    setSelectedKernel(index);
    setSelectedIR(null);

    // Update URL with the selected kernel hash
    if (loadedUrl && kernels[index]?.metadata?.hash) {
      const newUrl = new URL(window.location.href);
      newUrl.searchParams.set("kernel_hash", kernels[index].metadata.hash);
      window.history.replaceState({}, "", newUrl.toString());
    }
  };

  /**
   * Builds the shareable URL for the current single-trace view at click time.
   */
  const buildSingleTraceShareUrl = useCallback(() => {
    const shareableUrl = new URL(window.location.href);

    // Add or remove view parameter
    if (activeTab === "comparison") {
      shareableUrl.searchParams.set("view", "ir_code_comparison");
    } else if (activeTab === "ir_analysis") {
      shareableUrl.searchParams.set("view", "ir_analysis");
    } else {
      shareableUrl.searchParams.delete("view");
    }

    // Add or remove kernel_hash parameter
    if (selectedKernel >= 0 && kernels[selectedKernel]?.metadata?.hash) {
      shareableUrl.searchParams.set("kernel_hash", kernels[selectedKernel].metadata.hash);
    } else {
      shareableUrl.searchParams.delete("kernel_hash");
    }

    return shareableUrl.toString();
  }, [activeTab, selectedKernel, kernels]);

  // Register app controls for FileDiffSession navigation
  useEffect(() => {
    sess.registerAppControls({
      setActiveTab,
    });
  }, [sess, setActiveTab]);

  // Clear FileDiff preview when entering/returning to File Diff to avoid preview intercepting other views
  useEffect(() => {
    if (activeTab === 'file_diff' && sess.preview.active) {
      sess.clearPreview();
    }
  }, [activeTab, sess]);

  // Keep-alive bookkeeping: remember main tabs once visited so they stay
  // mounted while hidden. Transient states (single-IR, preview, welcome)
  // keep their exclusive rendering and are unaffected. React's documented
  // "adjust state during render" pattern (also used in FileDiffView and
  // TruncatedValue); the guard makes it fire at most once per new tab.
  if (
    (activeTab === "overview" || activeTab === "comparison" || activeTab === "file_diff" || activeTab === "ir_analysis") &&
    !visitedTabs.has(activeTab)
  ) {
    setVisitedTabs(new Set(visitedTabs).add(activeTab));
  }

  // Committed e2e fixture page: mounts the real comparison V2
  // with synthetic props and swap buttons. Only reachable through the
  // explicit ?view=comparison_fixture URL; normal flows never render it.
  if (initialParams.get("view") === "comparison_fixture") {
    return <ComparisonFixture />;
  }

  // Committed e2e fixture page: mounts the real Single
  // viewer with synthetic props and swap buttons. Only reachable through
  // the explicit ?view=single_fixture URL; normal flows never render it.
  if (initialParams.get("view") === "single_fixture") {
    return <SingleFixture />;
  }

  // Show loading indicator while data is being fetched
  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen w-full bg-gray-50 text-gray-800">
        <div className="text-center">
          <div className="text-xl mb-4">Loading Triton compilation data...</div>
          <div className="animate-pulse">Please wait...</div>
        </div>
      </div>
    );
  }

  /**
   * Renders the main content based on current state (selected IR, kernel, and active tab)
   */
  const renderContent = () => {
    if (selectedIR && selectedKernel >= 0 && kernels.length > 0) {
      // Display single IR view
      const kernel = kernels[selectedKernel];
      if (!kernel) {
        console.error(`Selected kernel index ${selectedKernel} not found in kernels array of length ${kernels.length}`);
        return <div className="text-red-600">Error: Selected kernel not found</div>;
      }

      const irContent = kernel.irFiles[selectedIR];
      if (!irContent) {
        console.error(`IR file ${selectedIR} not found in kernel ${kernel.name}`);
        return <div className="text-red-600">Error: Selected IR file not found in kernel</div>;
      }

      // Create IRFile object with content and potential source mapping
      const irFile = {
        content: irContent,
        // Add source mapping if available in the kernel data
        source_mapping: kernel.sourceMappings?.[getIRType(selectedIR)],
      };

      return (
        <SingleCodeViewer
          irFile={irFile}
          title={selectedIR}
          onBack={handleBackFromIRView}
          irStages={kernel?.ir_stages}
          sourceId={sourceIdentity}
          kernelId={kernel.metadata?.hash ?? selectedKernel}
        />
      );
    } else if (sess.preview.active) {
      const side = sess.preview.side === 'left' ? sess.left : sess.right;
      const idx = side.selectedIdx ?? 0;
      const kernelsSrc = side.kernels ?? [];
      if (!kernelsSrc || kernelsSrc.length === 0) {
        return <div className="text-red-600">Error: Preview kernel data not available.</div>;
      }
      if (sess.preview.view === 'overview') {
        return (
          <KernelOverview
            key={`preview-overview-${sess.preview.side}-${idx}`}
            kernels={kernelsSrc}
            onViewIR={handleViewSingleIR}
            selectedKernel={idx}
            onSelectKernel={() => {}}
          />
        );
      }
      if (sess.preview.view === 'ir') {
        return (
          <CodeView
            key={`preview-ir-${sess.preview.side}-${idx}`}
            kernels={kernelsSrc}
            selectedKernel={idx}
          />
        );
      }
      return null;
    } else if (!dataLoaded) {
      // Show welcome screen if no data is loaded, but allow File Diff tab to render its view when selected
      if (activeTab === 'file_diff') {
        return (
          <FileDiffView
            kernelsLeft={kernels}
            selectedLeftIndex={Math.max(0, selectedKernel)}
            leftLoadedUrl={loadedUrl}
          />
        );
      }
      return (
        <WelcomeScreen
          loadBundledExample={loadBundledExample}
          handleFileSelected={handleFileSelected}
          openUrlInput={openUrlInput}
        />
      );
    } else if (showWelcome && activeTab === "overview") {
      // Show welcome screen when user clicks title to go home (even when data is loaded)
      return (
        <WelcomeScreen
          loadBundledExample={loadBundledExample}
          handleFileSelected={handleFileSelected}
          openUrlInput={openUrlInput}
        />
      );
    } else if (kernels.length === 0) {
      // Show message when no kernels are found
      return (
        <div className="flex items-center justify-center p-8">
          <div className="bg-yellow-50 p-6 rounded-lg border border-yellow-200 max-w-2xl">
            <h2 className="text-xl font-semibold text-yellow-800 mb-3">No Kernel Data Found</h2>
            <p className="text-yellow-700">
              No Triton kernels were found in the log file. Please make sure you're using the correct log file and that
              it contains Triton kernel information.
            </p>
          </div>
        </div>
      );
    } else {
      // Show either overview, IR code, IR analysis, or file diff based on active tab.
      // Visited tabs stay mounted and inactive ones are hidden with display:none,
      // so switching tabs never pays unmount/remount (measured in seconds for
      // the Monaco diff editor and the full-DOM code viewers). Unvisited tabs
      // render nothing until first visit.
      const show = (tab: string) => (activeTab === tab ? undefined : "none");
      return (
        <>
          {visitedTabs.has("overview") && (
            <div style={{ display: show("overview") }}>
              <KernelOverview
                kernels={kernels}
                onViewIR={handleViewSingleIR}
                selectedKernel={selectedKernel}
                onSelectKernel={handleSelectKernel}
              />
            </div>
          )}
          {visitedTabs.has("ir_analysis") && (
            <div style={{ display: show("ir_analysis") }}>
              <IRAnalysis
                kernels={kernels}
                selectedKernel={selectedKernel}
              />
            </div>
          )}
          {visitedTabs.has("comparison") && (
            <div style={{ display: show("comparison") }}>
              <CodeView
                key={`codeview-main-${selectedKernel}`}
                kernels={kernels}
                selectedKernel={selectedKernel}
                sourceId={sourceIdentity}
              />
            </div>
          )}
          {visitedTabs.has("file_diff") && (
            <div style={{ display: show("file_diff") }}>
              <FileDiffView
                kernelsLeft={kernels}
                selectedLeftIndex={Math.max(0, selectedKernel)}
                leftLoadedUrl={loadedUrl}
              />
            </div>
          )}
        </>
      );
    }
  };

  // Helper: whether any trace/kernel data is available for enabling tabs
  const isTraceLoaded = dataLoaded && kernels.length > 0;

  // Helper to build class names for tab buttons
  const tabClassName = (isDisabled: boolean, isActive: boolean) =>
    `px-3 py-2 text-sm font-medium rounded-md ${
      isDisabled
        ? "bg-gray-100 text-gray-400 cursor-not-allowed"
        : isActive
        ? "bg-blue-700 text-white shadow-md"
        : "bg-blue-100 text-blue-700 hover:bg-blue-200"
    }`;

  // Factory to create tab buttons with consistent behavior and accessibility
  const makeTabButton = (opts: {
    label: string;
    isActive: boolean;
    requiresTrace?: boolean;
    includeSelectedIR?: boolean;
    onActivate: () => void;
    enabledTitle?: string;
    disabledTitle?: string;
  }) => {
    const {
      label,
      isActive,
      requiresTrace = true,
      includeSelectedIR = true,
      onActivate,
      enabledTitle,
      disabledTitle,
    } = opts;
    const isDisabled = (requiresTrace && !isTraceLoaded) || (includeSelectedIR && !!selectedIR);

    // Use aria-disabled + click guard so tooltip and keyboard users can discover the hint
    const handleClick = () => {
      if (isDisabled) return;
      onActivate();
    };

    const title = isDisabled ? disabledTitle ?? "Please load a trace file first" : enabledTitle ?? label;
    const descriptionId = isDisabled ? `tab-hint-${label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}` : undefined;

    return (
      <span className="group relative inline-flex focus-within:z-10">
        <button
          className={tabClassName(isDisabled, isActive)}
          aria-disabled={isDisabled}
          aria-describedby={descriptionId}
          onClick={handleClick}
        >
          {label}
        </button>
        {descriptionId && (
          <>
            <span id={descriptionId} className="sr-only">{title}</span>
            <span
              aria-hidden="true"
              className="pointer-events-none absolute left-1/2 top-full z-20 mt-2 -translate-x-1/2 whitespace-nowrap rounded-md bg-gray-900 px-2 py-1 text-xs text-white opacity-0 shadow-lg transition-opacity duration-150 group-hover:opacity-100 group-focus-within:opacity-100"
            >
              {title}
            </span>
          </>
        )}
      </span>
    );
  };

  return (
    <div className="min-h-screen w-full bg-gray-50 flex flex-col">
      {/* Header with navigation */}
      <header className="bg-white border-b border-gray-200">
        <div className="w-full px-6 py-4">
          <div className="flex justify-between items-center">
            <div className="flex items-center space-x-6">
              <h1
                className="text-gray-800 text-2xl font-bold cursor-pointer hover:text-indigo-600 transition-colors"
                onClick={() => {
                  // Clear preview state if active
                  if (sess.preview?.active) {
                    sess.clearPreview();
                  }
                  // Show welcome screen without clearing data
                  setShowWelcome(true);
                  setActiveTab("overview");
                  setSelectedIR(null);
                }}
                title="Back to home"
              >
                TritonParse
              </h1>

              {/* GitHub and Wiki Links */}
              <div className="flex items-center space-x-4">
                <ExternalLink
                  href="https://github.com/meta-pytorch/tritonparse"
                  title="View on GitHub"
                  text="GitHub"
                  icon={<GitHubIcon className="w-5 h-5" />}
                />

                <ExternalLink
                  href="https://github.com/meta-pytorch/tritonparse/wiki"
                  title="View Wiki"
                  text="Wiki"
                  icon={<BookOpenIcon className="w-5 h-5" />}
                />

                {/* Internal Wiki Link - only show in FB builds (compile-time determined) */}
                {import.meta.env.IS_FB_BUILD && (
                  <ExternalLink
                    href={import.meta.env.INTERNAL_WIKI_URL}
                    title="View Internal Wiki"
                    text="Internal Wiki"
                    icon={<BookOpenIcon className="w-5 h-5" />}
                  />
                )}
              </div>
            </div>

            {/* Data source selector (only show when data is loaded or when on the welcome screen) */}
            <DataSourceSelector
              onFileSelected={handleFileSelected}
              onUrlSelected={handleUrlSelected}
              isLoading={loading}
              showUrlInput={showUrlInput}
              onShowUrlInputChange={setShowUrlInput}
            />

            {/* Tab navigation: All buttons always visible; use shared helper for state, styling, and accessibility */}
            <div className="flex space-x-4">
              {makeTabButton({
                label: "Kernel Overview",
                isActive: activeTab === "overview",
                includeSelectedIR: true,
                onActivate: () => {
                  if (sess.preview?.active) sess.clearPreview();
                  setShowWelcome(false);
                  setActiveTab("overview");
                  if (loadedUrl) {
                    const newUrl = new URL(window.location.href);
                    newUrl.searchParams.delete("view");
                    window.history.replaceState({}, "", newUrl.toString());
                  }
                },
                enabledTitle: "View kernel overview",
                disabledTitle: "Please load a trace file first",
              })}

              {makeTabButton({
                label: "IR Code",
                isActive: activeTab === "comparison",
                includeSelectedIR: true,
                onActivate: () => {
                  if (sess.preview?.active) sess.clearPreview();
                  setShowWelcome(false);
                  setActiveTab("comparison");
                  if (loadedUrl) {
                    const newUrl = new URL(window.location.href);
                    newUrl.searchParams.set("view", "ir_code_comparison");
                    window.history.replaceState({}, "", newUrl.toString());
                  }
                },
                enabledTitle: "View IR code comparison",
                disabledTitle: "Please load a trace file first",
              })}

              {makeTabButton({
                label: "File Diff",
                isActive: activeTab === "file_diff",
                requiresTrace: false,
                includeSelectedIR: false,
                onActivate: () => {
                  if (sess.preview?.active) sess.clearPreview();
                  setShowWelcome(false);
                  setActiveTab("file_diff");
                },
                enabledTitle: "View file diff",
              })}

              {makeTabButton({
                label: "IR Analysis (Beta)",
                isActive: activeTab === "ir_analysis",
                includeSelectedIR: true,
                onActivate: () => {
                  if (sess.preview?.active) sess.clearPreview();
                  setShowWelcome(false);
                  setActiveTab("ir_analysis");
                  if (loadedUrl) {
                    const newUrl = new URL(window.location.href);
                    newUrl.searchParams.set("view", "ir_analysis");
                    window.history.replaceState({}, "", newUrl.toString());
                  }
                },
                enabledTitle: "View IR analysis",
                disabledTitle: "Please load a trace file first",
              })}
            </div>
          </div>
        </div>
      </header>

      {/* Main content */}
      <main className="w-full p-6 flex-grow">
        {/* Show error message if data loading failed */}
        {error && <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-6">{error}</div>}

        {/* Show loaded URL if available (File Diff owns its own Share button) */}
        {loadedUrl && dataLoaded && activeTab !== "file_diff" && (
          <div className="bg-blue-50 border border-blue-200 text-blue-700 px-4 py-3 rounded mb-6 flex items-center justify-between">
            <div>
              <span className="font-medium">Loaded from: </span>
              <span className="break-all">{loadedUrl}</span>
            </div>
            <span className="ml-4">
              <ShareButton getShareUrl={buildSingleTraceShareUrl} />
            </span>
          </div>
        )}

        {renderContent()}
      </main>

      {/* Footer with version info */}
      <footer className="w-full py-1 px-6 border-t border-gray-200 bg-white mt-auto">
        <div className="container mx-auto flex justify-between items-center text-sm">
          <div className="text-gray-500">
            Copyright © {new Date().getFullYear()} Meta Platforms, Inc
            <span className="mx-2">|</span>
            <a href="https://opensource.fb.com/legal/terms" className="hover:underline">Terms of Use</a>
            <span className="mx-2">|</span>
            <a href="https://opensource.fb.com/legal/privacy" className="hover:underline">Privacy Policy</a>
          </div>
          <div className="text-gray-500">
            {(() => {
              const buildDate = new Date(import.meta.env.PACKAGE_BUILD_DATE)
              const localized = isNaN(buildDate.getTime())
                ? import.meta.env.PACKAGE_BUILD_DATE
                : buildDate.toLocaleString()
              const sha = import.meta.env.GIT_COMMIT_SHA_SHORT
              return `Version ${import.meta.env.PACKAGE_VERSION} · Built ${localized} · ${sha}`
            })()}
          </div>
        </div>
      </footer>
    </div>
  );
}

export default App;
